import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"time"
)

func main() {
	url := "https://api.pingen.com/organisations/YOUR_ORGANISATION_UUID/deliveries/letters/price-calculator"
	accessToken := "INSERT_YOUR_ACCESS_TOKEN_HERE"

	payload := map[string]interface{}{
		"data": map[string]interface{}{
			"type": "letters",
			"attributes": map[string]interface{}{
				"country":          "CH",
				"paper_types":      []string{"normal", "qr"},
				"print_mode":       "simplex",
				"print_spectrum":   "color",
				"delivery_product": "fast",
			},
		},
	}

	payloadBytes, err := json.Marshal(payload)
	if err != nil {
		fmt.Println("Error marshalling payload:", err)
		return
	}

	req, err := http.NewRequest("POST", url, bytes.NewBuffer(payloadBytes))
	if err != nil {
		fmt.Println("Error creating POST request:", err)
		return
	}

	req.Header.Set("Content-Type", "application/vnd.api+json")
	req.Header.Set("Authorization", "Bearer "+accessToken)

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		fmt.Println("Error sending POST request:", err)
		return
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		fmt.Println("Error reading response body:", err)
		return
	}

	if resp.StatusCode == http.StatusOK {
		fmt.Println("Request successful (200 OK).")
		fmt.Println("Response:", string(body))
	} else if resp.StatusCode == http.StatusAccepted {
		fmt.Println("Request accepted (202 Accepted). Polling required to fetch the final status.")
		fmt.Println("Initial response:", string(body))

		for {
			time.Sleep(5 * time.Second)

			statusReq, err := http.NewRequest("POST", url, bytes.NewBuffer(payloadBytes))
			if err != nil {
				fmt.Println("Error creating polling request:", err)
				return
			}
			statusReq.Header.Set("Content-Type", "application/vnd.api+json")
			statusReq.Header.Set("Authorization", "Bearer "+accessToken)

			statusResp, err := client.Do(statusReq)
			if err != nil {
				fmt.Println("Error sending polling request:", err)
				continue
			}
			defer statusResp.Body.Close()

			statusBody, err := ioutil.ReadAll(statusResp.Body)
			if err != nil {
				fmt.Println("Error reading polling response body:", err)
				continue
			}

			if statusResp.StatusCode == http.StatusOK {
				fmt.Println("Polling successful. Final response:")
				fmt.Println(string(statusBody))
				break
			} else {
				fmt.Printf("Polling returned status %d. Retrying...\n", statusResp.StatusCode)
			}
		}
	} else {
		fmt.Printf("Request failed with status code: %d\n", resp.StatusCode)
		fmt.Println("Response:", string(body))
	}
}

