import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import org.json.JSONObject;

public class BatchCreation {
    public static void main(String[] args) {
        String urlFileUpload = "https://api.pingen.com/file-upload";
        String urlBatches = "https://api.pingen.com/organisations/YOUR_ORGANISATION_UUID/batches";
        String accessToken = "INSERT_YOUR_ACCESS_TOKEN_HERE";

        try {
            // Step 1: Get file upload URL and signature
            JSONObject fileUploadResponse = sendGetRequest(urlFileUpload, accessToken);
            JSONObject fileUploadData = fileUploadResponse.getJSONObject("data").getJSONObject("attributes");
            String fileUrl = fileUploadData.getString("url");
            String fileUrlSignature = fileUploadData.getString("url_signature");

            // Step 2: Upload the file to the file URL
            String filePath = "path_to_your_file.pdf"; // Replace with your file path
            uploadFile(fileUrl, filePath);

            // Step 3: Create a batch
            JSONObject payload = new JSONObject()
                    .put("data", new JSONObject()
                            .put("type", "batches")
                            .put("attributes", new JSONObject()
                                    .put("name", "Batch Name")
                                    .put("icon", "campaign")
                                    .put("file_original_name", "your_filename.pdf")
                                    .put("file_url", fileUrl)
                                    .put("file_url_signature", fileUrlSignature)
                                    .put("address_position", "left")
                                    .put("grouping_type", "merge")
                                    .put("grouping_options_split_type", "page")
                                    .put("grouping_options_split_size", 2)
                            )
                    );

            sendPostRequest(urlBatches, payload, accessToken);

        } catch (Exception e) {
            System.err.println("Error occurred: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private static JSONObject sendGetRequest(String urlString, String accessToken) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        connection.setRequestMethod("GET");
        connection.setRequestProperty("Authorization", "Bearer " + accessToken);

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                return new JSONObject(response.toString());
            }
        } else {
            throw new IOException("GET request failed. HTTP Status: " + responseCode);
        }
    }

    private static void uploadFile(String fileUrl, String filePath) throws IOException {
        URL url = new URL(fileUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        connection.setRequestMethod("PUT");
        connection.setDoOutput(true);

        try (OutputStream os = connection.getOutputStream();
             FileInputStream fis = new FileInputStream(filePath)) {

            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                os.write(buffer, 0, bytesRead);
            }
        }

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK || responseCode == HttpURLConnection.HTTP_NO_CONTENT) {
            System.out.println("File successfully uploaded!");
        } else {
            throw new IOException("File upload failed. HTTP Status: " + responseCode);
        }
    }

    private static void sendPostRequest(String urlString, JSONObject payload, String accessToken) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/vnd.api+json");
        connection.setRequestProperty("Authorization", "Bearer " + accessToken);
        connection.setDoOutput(true);

        try (OutputStream os = connection.getOutputStream()) {
            os.write(payload.toString().getBytes(StandardCharsets.UTF_8));
        }

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_CREATED) {
            System.out.println("Batch successfully created!");
        } else {
            throw new IOException("Batch creation failed. HTTP Status: " + responseCode);
        }
    }
}

