import java.io.BufferedReader;
import java.io.DataOutputStream;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class Main {

    public static void main(String[] args) {
        String url = "https://api.pingen.com/organisations/YOUR_ORGANISATION_UUID/webhooks";
        String accessToken = "INSERT_YOUR_ACCESS_TOKEN_HERE";

        String payload = "{"
                + "\"data\": {"
                + "\"type\": \"webhooks\","
                + "\"attributes\": {"
                + "\"event_category\": \"issues\","
                + "\"url\": \"https://valid-url\","
                + "\"signing_key\": \"d09a095a0d1d2ae896f985c0fff1ad51\""
                + "}"
                + "}"
                + "}";

        try {
            URL apiUrl = new URL(url);
            HttpURLConnection connection = (HttpURLConnection) apiUrl.openConnection();
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Authorization", "Bearer " + accessToken);
            connection.setRequestProperty("Content-Type", "application/vnd.api+json");
            connection.setDoOutput(true);

            try (DataOutputStream outputStream = new DataOutputStream(connection.getOutputStream())) {
                outputStream.writeBytes(payload);
                outputStream.flush();
            }

            int responseCode = connection.getResponseCode();

            if (responseCode == HttpURLConnection.HTTP_CREATED) {
                try (BufferedReader reader = new BufferedReader(
                        new InputStreamReader(connection.getInputStream()))) {
                    String line;
                    StringBuilder response = new StringBuilder();
                    while ((line = reader.readLine()) != null) {
                        response.append(line);
                    }
                    System.out.println("Webhook created successfully (201 Created).");
                    System.out.println("Response: " + response.toString());
                }
            } else {
                System.out.printf("Request failed with status code: %d%n", responseCode);
                try (BufferedReader reader = new BufferedReader(
                        new InputStreamReader(connection.getErrorStream()))) {
                    String line;
                    StringBuilder errorResponse = new StringBuilder();
                    while ((line = reader.readLine()) != null) {
                        errorResponse.append(line);
                    }
                    System.out.println("Error Response: " + errorResponse.toString());
                }
            }
        } catch (Exception e) {
            System.err.println("An error occurred during the request: " + e.getMessage());
        }
    }
}

